mapper.select:
/* 처방약 목록 조회(복용중 우선·최신순) */ SELECT P.PRSC_SN , P.CKUP_RCD_SN , P.MDCN_NM , P.MDCN_BGNG_YMD , P.MDCN_END_YMD , P.DAY_MDCN_NMTM , P.PRSC_STTS_CD , S.COM_CD_NM AS PRSC_STTS_CD_NM , CASE WHEN P.CARE_RFLT_YN = 'Y' THEN TRUE ELSE FALSE END AS CARE_RFLT_YN FROM PRSC P LEFT JOIN COM_CD S ON S.COM_CD = P.PRSC_STTS_CD AND S.COM_CD_PRNT_SN IS NOT NULL WHERE P.CKUP_RCD_SN = #{cond.ckupRcdSn} AND P.DEL_YN = 'N'
AND P.PRSC_STTS_CD = #{cond.prscSttsCd}
ORDER BY CASE WHEN P.PRSC_STTS_CD = #{takingCd} THEN 0 ELSE 1 END , P.MDCN_BGNG_YMD DESC , P.PRSC_SN DESC

/* 처방약 잠금 조회 */
SELECT

  FROM PRSC
 WHERE PRSC_SN = #{prscSn}
   AND DEL_YN = 'N'
   FOR UPDATE

/* 복용 종료일이 지난 복용중 처방약 */
SELECT

  FROM PRSC
 WHERE PRSC_STTS_CD = #{takingCd}
   AND MDCN_END_YMD < #{today}
   AND DEL_YN = 'N'
 ORDER BY PRSC_SN

mapper.insert:
/* 처방약 등록 */
INSERT INTO PRSC
     ( CKUP_RCD_SN
     , PRSC_STTS_CD
     , MDCN_NM
     , DAY_MDCN_NMTM
     , MDCN_BGNG_YMD
     , MDCN_END_YMD
     , CARE_RFLT_YN
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID
     , DEL_YN )
VALUES
     ( #{ckupRcdSn}
     , #{prscSttsCd}
     , #{mdcnNm}
     , #{dayMdcnNmtm}
     , #{mdcnBgngYmd}
     , #{mdcnEndYmd}
     , #{careRfltYn}
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId}
     , 'N' )

mapper.update:
/* 처방약 수정 */
UPDATE PRSC
   SET PRSC_STTS_CD  = #{prescription.prscSttsCd}
     , MDCN_NM       = #{prescription.mdcnNm}
     , DAY_MDCN_NMTM = #{prescription.dayMdcnNmtm}
     , MDCN_BGNG_YMD = #{prescription.mdcnBgngYmd}
     , MDCN_END_YMD  = #{prescription.mdcnEndYmd}
     , CARE_RFLT_YN  = #{prescription.careRfltYn}
     , MDFR_ID       = #{actorId}
     , MDFCN_DT      = NOW()
 WHERE PRSC_SN = #{prescription.prscSn}
   AND DEL_YN = 'N'

/* 처방약 삭제 */
UPDATE PRSC
   SET DEL_YN   = 'Y'
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE PRSC_SN = #{prscSn}
   AND DEL_YN = 'N'

